import machines from '../data/htb-machines.json';

export interface HtbMachine {
  name: string;
  difficulty: string;
  os: string;
  released: string;
  rating: string;
  avatar: string;
  description: string;
}

// Machine info is generated by scripts/fetch-htb.mjs (npm run htb) and can be edited by hand.
export function getMachine(slug: string): HtbMachine {
  const machine = (machines as Record<string, HtbMachine>)[slug];
  if (!machine) {
    throw new Error(`[htb] No machine info for "${slug}" in src/data/htb-machines.json. Run "npm run htb" with HTB_API_TOKEN set in .env.`);
  }
  return machine;
}
